"""Discussion questions for judges, generated by rules from the reviewed data (spec §11).

Rule-based on purpose: they can only point at what the record shows, never invent issues."""

from __future__ import annotations

from typing import TYPE_CHECKING

if TYPE_CHECKING:
    from app.services.reports.data import FinalistReport, ReportData

MAX_ITEMS = 5


def finalist_questions(f: FinalistReport) -> list[str]:
    questions: list[str] = []
    if f.score_display is None:
        questions.append(
            f"{f.criteria_total - f.criteria_assessed} criterion rating(s) are missing or were "
            "rejected. Should the nominee be re-assessed before deliberation?"
        )
    if f.is_tie and f.tied_with:
        questions.append(
            f"The nominee is tied with {', '.join(f.tied_with)}. Which criteria should decide, "
            "pending the committee's tie-break procedure?"
        )
    for r in f.criteria:
        if r.reviewer_rating is not None and r.ai_rating is not None:
            questions.append(
                f"A reviewer adjusted {r.name} from {r.ai_rating} to {r.reviewer_rating}"
                + (f" ({r.review_notes.rstrip('. ')})" if r.review_notes else "")
                + ". Does the panel agree?"
            )
        if r.changed_since_snapshot and r.current_rating is not None:
            questions.append(
                f"{r.name} was reviewed after this ranking was calculated (now "
                f"{r.current_rating}). Should the ranking be recalculated?"
            )
    insufficient = [r.name for r in f.criteria if r.sufficiency == "insufficient"]
    if insufficient:
        questions.append(
            f"Evidence was insufficient for {', '.join(insufficient)}. Is more information "
            "needed from the nominator, bearing in mind that confidential board work may "
            "not be publicly documented?"
        )
    for statement, status in f.unresolved_claims[:MAX_ITEMS]:
        if status == "disputed":
            questions.append(f"The claim “{statement}” is disputed. Which evidence should prevail?")
        elif status == "missing":
            questions.append(
                f"The claim “{statement}” lacks its supporting evidence. Should "
                "the nominator be asked for it?"
            )
    for description in f.unresolved_contradictions[:MAX_ITEMS]:
        questions.append(f"Unresolved contradiction: {description} How should it be resolved?")
    if f.unreviewed:
        questions.append(
            f"{len(f.unreviewed)} rating(s) have not had human quality review. Should they be "
            "reviewed before the panel relies on them?"
        )
    return questions


def category_questions(data: ReportData) -> list[str]:
    questions: list[str] = []
    ties: dict[str, list[str]] = {}
    for f in data.finalists:
        if f.is_tie and f.score_display:
            ties.setdefault(f.score_display, []).append(f.name)
    for score, names in ties.items():
        questions.append(
            f"{' and '.join(names)} are tied at {score}. Which criteria should "
            "decide, pending the committee's tie-break procedure?"
        )
    for higher, lower, gap in data.close_results:
        if gap != "0.00":
            questions.append(
                f"{higher} leads {lower} by only {gap}. Is the difference "
                "meaningful given the evidence behind each rating?"
            )
    for spread in data.spreads[:3]:
        if spread.size >= 2:
            questions.append(
                f"On {spread.criterion}, {', '.join(spread.highest)} rated {spread.high} and "
                f"{', '.join(spread.lowest)} rated {spread.low}. Do the judges agree with this "
                "difference?"
            )
    unscored = [f.name for f in data.finalists if f.score_display is None]
    if unscored:
        questions.append(
            f"{', '.join(unscored)} could not be scored (missing or rejected "
            "ratings). Should they be re-assessed before a decision?"
        )
    pending = sum(len(f.unreviewed) for f in data.finalists)
    if pending:
        questions.append(f"{pending} rating(s) across the category have not been reviewed.")
    if not data.production:
        questions.append(
            "The rubric is not frozen, so this is a practice ranking. Approve and "
            "freeze the committee's criteria before relying on it."
        )
    return questions
